    struct Stats s = {0, 0, 0.0};
    // Заполните s.
    return s;
}

int main(void) {
    int n;
    scanf("%d", &n);
    int values[1000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    struct Stats s = analyze(values, n);
    printf("%d %d %.2f\n", s.min, s.max, s.mean);
    return 0;
}

additionalExercises.referenceSolution:
#include <stdio.h>

struct Stats {
    int min;
    int max;
    double mean;
};

struct Stats analyze(const int *values, int n) {
    struct Stats s = {values[0], values[0], 0.0};
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        if (values[i] < s.min) {
            s.min = values[i];
        }
        if (values[i] > s.max) {
            s.max = values[i];
        }
        sum += values[i];
    }
    s.mean = (double)sum / n;
    return s;
}

int main(void) {
    int n;
    scanf("%d", &n);
    int values[1000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    struct Stats s = analyze(values, n);
    printf("%d %d %.2f\n", s.min, s.max, s.mean);
    return 0;
}

