#include <stdio.h>
#include <string.h>

const char *to_binary(unsigned x) {
    static char buffer[33];
    int pos = 32;
    buffer[pos] = '\0';
    do {
        buffer[--pos] = (char)('0' + x % 2);
        x /= 2;
    } while (x > 0);
    return buffer + pos;
}

int main(void) {
    int q;
    scanf("%d", &q);
    for (int i = 0; i < q; i++) {
        unsigned a, b;
        scanf("%u %u", &a, &b);
        const char *left = to_binary(a);
        const char *right = to_binary(b);
        printf("%s %s\n", left, right);
    }
    return 0;
}

